// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    Attacker attacker;

    function setUp() public { c = new MY_BANK(address(new Log())); }

    // fuzz parameters:
    // - uint96 deposit : amount to deposit and attempt to collect (fuzzer will pick)
    // - uint96 collectAmt : amount to collect (fuzzer will pick)
    // We keep them as uint96 to ensure vm.deal and value fits comfortably.
    function testFuzz_property(uint96 deposit, uint96 collectAmt) public {
        // Keep values in a reasonable wide range but non-zero
        uint256 dep = bound(uint256(deposit), 1 wei, 5 ether);
        uint256 am  = bound(uint256(collectAmt), 1 wei, 5 ether);

        // Deploy a recording reentrant attacker that will re-enter Collect exactly once
        attacker = new Attacker(c);

        // Arrange: give the attacker enough ETH to call Put (deposit)
        vm.deal(address(attacker), dep);

        // attacker will call Put to set its Acc balance and set unlockTime to past so Collect can proceed
        attacker.doPut{value: dep}(address(c), 0);

        // Ensure the deposit is at least the contract's MinSum so Collect may succeed
        uint256 minSum = c.MinSum();
        vm.assume(dep >= minSum && am <= dep); // admissible domain: deposit >= MinSum and trying to collect <= balance

        // Warp time forward so unlockTime condition (block.timestamp>acc.unlockTime) becomes true
        vm.warp(block.timestamp + 1 hours);

        // Now attacker will call Collect on c and in its receive() it will reenter Collect exactly once
        // We observe balance before and after via public getter Acc(address)
        (uint256 beforeUnlockTime, uint256 beforeBalance) = c.Acc(address(attacker));

        // perform the collect via attacker which will attempt reentrancy
        bool ok;
        try attacker.attackCollect(address(c), am) {
            ok = true;
        } catch {
            ok = false;
        }

        (uint256 afterUnlockTime, uint256 afterBalance) = c.Acc(address(attacker));

        // GENERAL RULE: For the correct contract, after a successful Collect call the caller's balance decreases by exactly the collected amount.
        // We express this as: if the external call returned (ok==true), then beforeBalance - afterBalance == am.
        // This must hold for all admissible inputs on the reference contract. The mutant that removed the require(!locked_) can allow a reentrant second Collect execution before the balance update, causing afterBalance to be larger than expected (i.e., before - after != am) for some inputs; the fuzz will find such inputs.
        if (ok) {
            assertTrue(beforeBalance - afterBalance == am);
        } else {
            // If the call reverted, the reference contract might revert only when external Log address has no code or on bad conditions.
            // For the admissible domain we've set up (Log exists and preconditions hold), ok should be true on the reference; still, don't assert on reverted path.
            assertTrue(beforeBalance >= afterBalance);
        }
    }
}

// Adversarial reentrant caller. It will receive ETH when c sends value and on first receive it will re-enter c.Collect exactly once.
contract Attacker {
    MY_BANK immutable target;
    bool private reentered;

    constructor(MY_BANK _c) {
        target = _c;
    }

    // Do Put to set up balance and unlockTime; called by test with vm.prank implicitly via this contract
    function doPut(address caddr, uint256 unlockTime) external payable {
        // direct call to target.Put
        target.Put{value: msg.value}(unlockTime);
    }

    // Kick off the Collect call; this will cause target to call back to this contract when it sends ETH,
    // and our receive() will re-enter Collect exactly once.
    function attackCollect(address caddr, uint256 am) external {
        target.Collect{value: 0}(am);
    }

    // receive will be invoked when target sends ETH. Re-enter Collect exactly once.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // try to reenter Collect for the same amount; this models an attacker that re-enters during the external call
            // Use try/catch to avoid bubbling any revert outward; we allow it to fail silently here.
            try target.Collect{value: 0}(msg.value) {
            } catch {
            }
        }
    }
}
